const add: (a: number, b: number) => number = (x, y) => x + y;
const fib = (n: number): number => (n < 2 ? n : fib(n - 1) + fib(n - 2));
const fact = function g(n: number): number { return n <= 1 ? 1 : n * g(n - 1); };
const handlers: { on: (cb: (v: string) => void) => void } = { on(cb) { cb("hi"); } };
function main(): void { console.log(add(1, 2), fib(15), fact(5)); handlers.on((v) => console.log(v)); }
